package practice;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * Pages the results of one list endpoint. A request may ask for its own page size with the
 * {@code pageSize} query parameter; the JSON decoder hands parameters over as plain objects.
 */
public class Pagination {

    /** The largest page size a request may ask for. */
    static final int MAX_PAGE_SIZE = 500;

    private final int pageSize;                        // this endpoint's default
    private final List<String> warnings = new ArrayList<>();

    public Pagination(int pageSize) {
        this.pageSize = pageSize;
    }

    /** Returns the first page of {@code items} for a request with the given query parameters. */
    public <T> List<T> firstPage(List<T> items, Map<String, Object> query) {
        return items.subList(0, Math.min(items.size(), pageSizeFor(query)));
    }

    /** The warnings recorded so far, oldest first. */
    public List<String> warnings() {
        return List.copyOf(warnings);
    }

    /**
     * The page size for one request: the query's {@code pageSize} when it is an Integer from 1
     * to MAX_PAGE_SIZE, this endpoint's default otherwise. A value that is there but can't be
     * used is recorded in the warnings, so that support can tell the client what was wrong.
     */
    int pageSizeFor(Map<String, Object> query) {
        Object raw = query.get("pageSize");
        if (raw == null) return pageSize;
        if (raw instanceof Integer size && size >= 1 && size <= MAX_PAGE_SIZE) return size;
        warnings.add("ignored pageSize " + raw);
        return pageSize;
    }
}

package practice;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.IntStream;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            List<Integer> orders = IntStream.rangeClosed(1, 200).boxed().toList();
            Pagination pagination = new Pagination(25);
            Map<String, Object> asked = new HashMap<>(Map.of("pageSize", 60));
            Map<String, Object> none = new HashMap<>(Map.of("sort", "total"));
            System.out.println("pageSize 60: " + pagination.pageSizeFor(asked));
            System.out.println("no pageSize: " + pagination.pageSizeFor(none));
            System.out.println("pageSize \"30\": " + pagination.pageSizeFor(new HashMap<>(Map.of("pageSize", "30"))));
            System.out.println("pageSize 750: " + pagination.pageSizeFor(new HashMap<>(Map.of("pageSize", 750))));
            System.out.println("first page size: " + pagination.firstPage(orders, asked).size());
            System.out.println("warnings: " + pagination.warnings());
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

